    $future=$state['anio'].'-'.str_pad((string)$n,2,'0',STR_PAD_LEFT)>date('Y-m'); ?>
<tr><th scope="row"><?= e(\App\Services\ExtractoData::MONTHS[$n]) ?></th><td><?= $month['bruto']===null?($future?'Por recibir':'Falta comprobante'):'$'.e(number_format($month['bruto'],0,',','.')) ?></td><td><?= $month['salud']===null?'—':'$'.e(number_format($month['salud'],0,',','.')) ?></td>
<td><?= $month['bruto']===null?'—':'$'.e(number_format($pensionGrossSum,0,',','.')) ?></td><td><?= $month['neto']===null?'—':e(\App\Services\ExtractoData::money($month['neto'])) ?></td><td><?= $month['neto']===null?'—':e(\App\Services\ExtractoData::money($pensionNetSum)) ?></td>
<td><?php foreach ($month['comprobantes'] as $id): ?><button class="text-secondary underline" type="button" data-pension-open="<?= $id ?>">Comprobante</button> <?php endforeach; ?><?php foreach ($month['bancos'] as $bank): ?><a class="text-secondary underline" href="<?= e(url($config,'registro').\App\Services\RegistroNavegacion::query($state,(int)$taxpayer['id']).'&documento='.$bank['id'].'#detalle') ?>"><?= e('Ver movimientos y PDF aquí · '.$bank['label']) ?></a> <?php endforeach; ?></td></tr>
<?php endforeach; ?></tbody><tfoot><tr><th>Total registrado</th><td><?= $hasGross?'$'.e(number_format($pensionGrossSum,0,',','.')):'Pendiente' ?></td><td><?= $hasHealth?'$'.e(number_format($pensionHealthSum,0,',','.')):'Pendiente' ?></td><td>Parcial si faltan meses</td><td><?= $hasNet?e(\App\Services\ExtractoData::money($pensionNetSum)):'Pendiente' ?></td><td>—</td><td>Soportes del año seleccionado</td></tr></tfoot></table></div>
<details><summary class="text-secondary underline">? · Cómo leer los pendientes</summary><p>«Falta comprobante» o «—» significa información pendiente, no cero. Un PDF bancario sin lectura no aporta valores. Los documentos ya guardados se conservan y se consultan desde su mes.</p></details>
